/**
 * BEST BOTTLES - Create Roll-On Product Documents
 * 
 * ============================================================
 * PURPOSE: Create productRollOn documents from imported assets
 * ============================================================
 * 
 * This script reads the asset-mapping.json (generated by import-roll-on-assets.mjs)
 * and creates product documents in Sanity using the uploaded Asset IDs.
 * 
 * USAGE:
 *   node scripts/create-roll-on-products.mjs
 * 
 * PREREQUISITES:
 *   - Run import-roll-on-assets.mjs first to generate asset-mapping.json
 *   - SANITY_API_TOKEN environment variable
 * 
 * ============================================================
 */

import { createClient } from '@sanity/client'
import * as fs from 'fs'
import * as path from 'path'
import { fileURLToPath } from 'url'

const __filename = fileURLToPath(import.meta.url)
const __dirname = path.dirname(__filename)

// ============================================================
// CONFIGURATION
// ============================================================

const SANITY_PROJECT_ID = 'gv4os6ef'
const SANITY_DATASET = 'production'
const SANITY_API_VERSION = '2024-01-01'
const SANITY_API_TOKEN = process.env.SANITY_API_TOKEN || ''

if (!SANITY_API_TOKEN) {
  console.error('❌ SANITY_API_TOKEN is required')
  process.exit(1)
}

const client = createClient({
  projectId: SANITY_PROJECT_ID,
  dataset: SANITY_DATASET,
  apiVersion: SANITY_API_VERSION,
  token: SANITY_API_TOKEN,
  useCdn: false,
})

// ============================================================
// PRICING DATA (from scraped data)
// ============================================================

const PRICING = {
  'cyl-9ml-clear': 0.67,
  'cyl-9ml-amber': 0.69,
  'cyl-9ml-blue': 0.72,
  'cyl-9ml-frosted': 0.77,
  'cyl-9ml-swirl': 0.79,
}

// ============================================================
// MAIN FUNCTION
// ============================================================

async function createProducts() {
  console.log(`
╔════════════════════════════════════════════════════════════════╗
║  BEST BOTTLES - Create Roll-On Products                        ║
╚════════════════════════════════════════════════════════════════╝
`)

  // Load asset mapping
  const mappingPath = path.join(__dirname, '../asset-mapping.json')
  
  if (!fs.existsSync(mappingPath)) {
    console.error(`
❌ asset-mapping.json not found!
   Run this first: node scripts/import-roll-on-assets.mjs
`)
    process.exit(1)
  }

  const mapping = JSON.parse(fs.readFileSync(mappingPath, 'utf-8'))
  console.log(`📂 Loaded asset mapping from ${mapping.generatedAt}`)
  console.log(`   - ${mapping.bottles.length} bottles`)
  console.log(`   - ${mapping.caps.length} caps`)
  console.log(`   - ${mapping.fitments.length} fitments`)

  // Create sample products (one per bottle, with default cap and fitment)
  const defaultCap = mapping.caps.find(c => c.originalId === 'black-dot') || mapping.caps[0]
  const defaultFitment = mapping.fitments.find(f => f.originalId === 'metal-roller') || mapping.fitments[0]

  console.log(`\n🔧 Creating products with:`)
  console.log(`   Default Cap: ${defaultCap?.name}`)
  console.log(`   Default Fitment: ${defaultFitment?.name}`)
  console.log('─'.repeat(60))

  const createdProducts = []

  for (const bottle of mapping.bottles) {
    const title = `9ML Roll-On - ${bottle.name} / ${defaultCap.name} / ${defaultFitment.name}`
    const slug = `9ml-roll-on-${bottle.originalId}`
    const price = PRICING[bottle.originalId] || 0.75

    console.log(`\n📦 Creating: ${title}`)

    try {
      const product = await client.create({
        _type: 'productRollOn',
        title,
        slug: { current: slug },
        price,
        description: `Premium 9ML cylinder roll-on bottle with ${bottle.name.toLowerCase()}, ${defaultFitment.name.toLowerCase()}, and ${defaultCap.name.toLowerCase()}. Perfect for perfume, essential oils, and aromatherapy applications.`,
        composition: {
          baseGlass: {
            _type: 'image',
            asset: {
              _type: 'reference',
              _ref: bottle.assetId,
            },
            alt: `${bottle.name} 9ML Roll-On Bottle`,
          },
          fitmentComponent: {
            _type: 'image',
            asset: {
              _type: 'reference',
              _ref: defaultFitment.assetId,
            },
            alt: defaultFitment.name,
            offsetY: -20, // Position the fitment above the bottle neck
          },
          capComponent: {
            _type: 'image',
            asset: {
              _type: 'reference',
              _ref: defaultCap.assetId,
            },
            alt: defaultCap.name,
            offsetY: -40, // Position the cap at the top
          },
        },
      })

      console.log(`   ✅ Created: ${product._id}`)
      createdProducts.push({
        id: product._id,
        title,
        slug,
        bottle: bottle.name,
      })
    } catch (error) {
      console.error(`   ❌ Error: ${error.message}`)
    }
  }

  // ────────────────────────────────────────────────────────
  // SUMMARY
  // ────────────────────────────────────────────────────────
  console.log('\n')
  console.log('═'.repeat(70))
  console.log('  PRODUCTS CREATED')
  console.log('═'.repeat(70))

  for (const product of createdProducts) {
    console.log(`  ✅ ${product.title}`)
    console.log(`     ID: ${product.id}`)
    console.log(`     URL: http://localhost:3000/studio/structure/productRollOn;${product.id}`)
  }

  console.log('\n')
  console.log('╔════════════════════════════════════════════════════════════════╗')
  console.log(`║  Created ${createdProducts.length} products!                                        ║`)
  console.log('╠════════════════════════════════════════════════════════════════╣')
  console.log('║  NEXT STEPS:                                                   ║')
  console.log('║  1. Open Sanity Studio: http://localhost:3000/studio           ║')
  console.log('║  2. Click "🧪 MVP: 9ML Roll-On" in the sidebar                 ║')
  console.log('║  3. View the "Exploded View Preview" tab on any product        ║')
  console.log('╚════════════════════════════════════════════════════════════════╝')

  return createdProducts
}

// ============================================================
// RUN
// ============================================================

createProducts()
  .then(() => process.exit(0))
  .catch((error) => {
    console.error('💥 Fatal error:', error)
    process.exit(1)
  })

